import {registerCatalog,localizedText} from './i18n.js';
registerCatalog('guidedAnnual',{en:{open:'Open reviewed annual valuation',scope:'A company-specific Year-by-year case is available. Its dated operating value and explicit capital assumptions remain separate from this Guided draft.',loading:'The annual workspace is still loading. Your Guided draft is unchanged; try again shortly.'},'zh-Hans':{open:'打开经审阅的年度估值',scope:'可使用公司专属的逐年情景。其历史时点营业价值及显式资本假设与此引导式草稿相互独立。',loading:'年度工作区仍在加载。您的引导式草稿不变；请稍后重试。'}});
export function guidedAnnualAvailabilityHTML(ticker){return ['NBIS','TSM'].includes(ticker)?`<p>${localizedText('guidedAnnual.scope')}</p><button type="button" class="primary" data-guided-open-annual>${localizedText('guidedAnnual.open')}</button><p data-guided-annual-status class="micro" role="status"></p>`:'';}
export function bindGuidedAnnualAvailability(root,ticker,{open}={}){const button=root?.querySelector('[data-guided-open-annual]');if(!button)return;button.onclick=()=>{try{const navigate=open||globalThis.document?.querySelector('#renewed-research-app')?.openCompany;if(typeof navigate!=='function')throw Error('loading');navigate(ticker);}catch{const status=root.querySelector('[data-guided-annual-status]');if(status)status.innerHTML=localizedText('guidedAnnual.loading');}};}
